using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;
internal sealed partial class ControlWindow {
 readonly Label discoveryHint=new Label(),sourceHint=new Label();readonly System.Windows.Forms.Timer discoveryTimer=new System.Windows.Forms.Timer();readonly ToolTip sourceTip=new ToolTip();
 ImportOperation discoveryOperation;FileSystemWatcher recordWatch,resourceWatch;bool discoveryBusy;int discoveryDirty=1;long discoveryChangedTicks;DateTimeOffset discoveryNext=DateTimeOffset.MinValue,lastSourceCheck=DateTimeOffset.MinValue;string discoveryPresentation="";SourceRootState sourceState;
 void MarkDiscoveryDirty(){Interlocked.Exchange(ref discoveryChangedTicks,DateTimeOffset.UtcNow.UtcTicks);Interlocked.Exchange(ref discoveryDirty,1);}
 void StartDiscovery(){
#if TEST_BUILD
  if(File.Exists(Path.Combine(Common.AppRoot,"tests/no-auto-discovery")))return;
#endif
  sourceState=SourceLocation.GetState();lastSourceCheck=DateTimeOffset.UtcNow;RefreshSourcePresentation();ConfigureSourceWatchers();discoveryHint.Text=sourceState.Found?"正在检查已知位置中的本机壁纸来源…":"当前没有可用的本机来源；可以浏览已有来源或添加CWP文件。";
  discoveryTimer.Interval=1000;discoveryTimer.Tick+=async(s,e)=>{if(closing)return;await TickOfficialNames();if(closing)return;var now=DateTimeOffset.UtcNow;if(now-lastSourceCheck>=TimeSpan.FromSeconds(30)){lastSourceCheck=now;RefreshSourceState(true);}if(discoveryBusy||importDialog!=null||importOperation!=null&&importOperation.Busy||sourceState==null||!sourceState.Found)return;bool dirty=Interlocked.CompareExchange(ref discoveryDirty,0,0)!=0;if(now<discoveryNext&&!dirty)return;if(dirty&&now.UtcTicks-Interlocked.Read(ref discoveryChangedTicks)<TimeSpan.FromSeconds(2).Ticks)return;await ProbeDiscovery();};
  discoveryTimer.Start();Write("discovery-started",new{scope="known cache_info and dynamic only, app lifetime only",sourceCondition=sourceState==null?"unknown":sourceState.Condition,recordEnumerationDeferredToOwnedWorker=true,systemBackgroundProcess=false,startupChanged=false,baselineHistoryIsNotNew=true});
 }
 async Task ProbeDiscovery(){
  if(closing||discoveryBusy||importDialog!=null||importOperation!=null&&importOperation.Busy)return;
  if(sourceState==null||!sourceState.Found){RefreshSourceState(false);return;}
  discoveryBusy=true;Interlocked.Exchange(ref discoveryDirty,0);discoveryOperation=new ImportOperation(Write);
  try{var data=await discoveryOperation.Run("discover",null,null,0,library.Doc.Items.Select(x=>x.RegisteredSha256).Where(x=>x!=null).ToArray());var summary=Common.Json.Deserialize<DiscoverySummary>(Common.Json.Serialize(data["discovery"]));
   if(closing)return;foreach(var candidate in summary.Candidates)if(PackageAnalysis.HashText(candidate.DiscoveredSha256))candidate.CoverSourceSha256=candidate.DiscoveredSha256;OfficialNameStore.ApplySaved(summary.Candidates);ApplyOfficialNames(summary.Candidates);string text=DiscoveryPresentation.Text(summary);
   if(text!=discoveryHint.Text){discoveryPresentation=text;discoveryHint.Text=text;Write("discovery-notice",new{outcome=summary.Outcome,recordsSeen=summary.RecordsSeen,validRecords=summary.ValidRecords,missingResources=summary.MissingResources,corruptRecords=summary.CorruptRecords,unsupportedRecords=summary.UnsupportedRecords,readFailures=summary.ReadFailures,unstableResources=summary.UnstableResources,completeNew=summary.UnreadComplete,pending=summary.Pending,text=text,noAutoplay=true});}
   Write("discovery-check",new{outcome=summary.Outcome,recordsSeen=summary.RecordsSeen,validRecords=summary.ValidRecords,missingResources=summary.MissingResources,corruptRecords=summary.CorruptRecords,unsupportedRecords=summary.UnsupportedRecords,readFailures=summary.ReadFailures,unstableResources=summary.UnstableResources,candidates=summary.Candidates.Count,unreadComplete=summary.UnreadComplete,pending=summary.Pending,hashedBytes=summary.HashedBytes,firstBaseline=summary.FirstBaseline,coverReads=0,network=false});discoveryNext=DateTimeOffset.UtcNow.AddSeconds(summary.Pending>0?15:30);
  }catch(OperationCanceledException){}catch(Exception ex){if(!closing){string text="联想缓存检查未完成。可以更改来源、添加已有CWP文件，或稍后重试。";if(discoveryHint.Text!=text)discoveryHint.Text=text;Write("discovery-check-failed",new{reason=ex.GetType().Name});}discoveryNext=DateTimeOffset.UtcNow.AddSeconds(30);}
  finally{discoveryBusy=false;}
 }
 async Task PauseDiscovery(){if(discoveryOperation!=null&&discoveryOperation.Busy)await discoveryOperation.Stop();}
 async Task StopDiscovery(){discoveryTimer.Stop();await StopNameFlow();if(recordWatch!=null){recordWatch.Dispose();recordWatch=null;}if(resourceWatch!=null){resourceWatch.Dispose();resourceWatch=null;}await PauseDiscovery();Write("discovery-close-clean",new{busy=discoveryBusy,scope="only owned discovery task"});}
 void RefreshSourceState(bool reconcile){var prior=sourceState;sourceState=SourceLocation.GetState();RefreshSourcePresentation();if(reconcile&&(prior==null||prior.Found!=sourceState.Found||prior.SavedCustom!=sourceState.SavedCustom||!String.Equals(prior.Root,sourceState.Root,StringComparison.OrdinalIgnoreCase)||!String.Equals(prior.Error,sourceState.Error,StringComparison.Ordinal))){ConfigureSourceWatchers();MarkDiscoveryDirty();discoveryNext=DateTimeOffset.MinValue;}}
 void RefreshSourcePresentation(){if(sourceHint.IsDisposed)return;if(sourceState==null||!sourceState.Found){sourceHint.Text=sourceState!=null&&sourceState.SavedCustom?"已保存的壁纸来源不可用 · 更改":"尚未找到本机壁纸来源 · 浏览已有来源";sourceHint.ForeColor=Color.FromArgb(157,82,28);sourceHint.AccessibleDescription=sourceState==null?"壁纸来源状态未知":(sourceState.Error??"默认位置不存在或不符合已知缓存布局")+"；可以更改来源或添加已有CWP文件";sourceTip.SetToolTip(sourceHint,sourceState==null?"检查或浏览本机已有壁纸来源":(sourceState.Error??"已检查默认位置："+sourceState.Root)+"\n软件登记和已导入资源会保留。");RefreshEmptyState();return;}sourceHint.Text=(sourceState.SavedCustom?"已找到自选壁纸来源：":"已识别本机壁纸缓存布局：")+sourceState.Root+" · 更改";sourceHint.ForeColor=Muted;sourceHint.AccessibleDescription="仅检查已知cache_info与wallpaper\\wpcache\\dynamic目录；目录识别不等于记录或壁纸文件已通过导入校验。联想缓存不会搬动。当前路径："+sourceState.Root;sourceTip.SetToolTip(sourceHint,sourceState.Root+"\n只检查已知缓存布局，不递归搜索、不复制缓存。记录数量和可导入状态由后台核查。");RefreshEmptyState();}
 void ConfigureSourceWatchers(){if(recordWatch!=null){recordWatch.Dispose();recordWatch=null;}if(resourceWatch!=null){resourceWatch.Dispose();resourceWatch=null;}if(sourceState==null||!sourceState.Found)return;try{string records=Path.Combine(sourceState.Root,"cache_info"),files=Path.Combine(sourceState.Root,"wallpaper","wpcache","dynamic");Action<string,string,bool> watch=(path,filter,isRecords)=>{if(!Directory.Exists(path))return;LocalImport.NoLinks(path);var w=new FileSystemWatcher(path,filter){IncludeSubdirectories=false,NotifyFilter=NotifyFilters.FileName|NotifyFilters.LastWrite|NotifyFilters.Size,InternalBufferSize=8192};FileSystemEventHandler changed=(s,e)=>MarkDiscoveryDirty();RenamedEventHandler renamed=(s,e)=>MarkDiscoveryDirty();w.Created+=changed;w.Changed+=changed;w.Deleted+=changed;w.Renamed+=renamed;w.Error+=(s,e)=>MarkDiscoveryDirty();w.EnableRaisingEvents=true;if(isRecords)recordWatch=w;else resourceWatch=w;};watch(records,"*.dat",true);watch(files,"*.cwp",false);}catch(Exception ex){Write("discovery-watch-fallback",new{reason=ex.GetType().Name,periodicKnownDirectoryReconciliation=true});}}
 async void ChooseSourceLocation(){if(closing||transition)return;using(var dialog=new FolderBrowserDialog{Description="选择本机已有的联想壁纸缓存根目录。程序只使用其中已知的cache_info与wallpaper\\wpcache\\dynamic布局，不递归搜索、不复制或搬动缓存。",ShowNewFolderButton=false,SelectedPath=sourceState!=null&&Directory.Exists(sourceState.Root)?sourceState.Root:SourceLocation.DefaultRoot}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;string old=File.Exists(SourceLocation.ConfigPath)?Common.Hash(SourceLocation.ConfigPath):null;try{string path=SourceLocation.SaveRoot(dialog.SelectedPath);RefreshSourceState(false);ConfigureSourceWatchers();MarkDiscoveryDirty();discoveryNext=DateTimeOffset.MinValue;Write("wallpaper-source-saved",new{path=path,recordFiles=sourceState.RecordFiles,usedByDiscovery=DataLocation.Same(LocalImport.DataRoot,path),cacheCopied=false,network=false});await ProbeDiscovery();}catch(Exception ex){RefreshSourcePresentation();Write("wallpaper-source-rejected",new{reason=ex.Message,previousConfigPreserved=old==null?!File.Exists(SourceLocation.ConfigPath):File.Exists(SourceLocation.ConfigPath)&&Common.Hash(SourceLocation.ConfigPath)==old});MessageBox.Show(this,"没有更改已保存的壁纸来源。\n\n"+ex.Message,"壁纸来源未更改",MessageBoxButtons.OK,MessageBoxIcon.Information);}}}
}
